questionvariables.text:
validate_point(ex) := if listp(ex) and length(ex) = 2 and listofvars(ex) = [] then "" else "Drag the point on the grid.";
col(v) := matrix([v[1]],[v[2]]);
near(p, q) := is(abs(p[1]-q[1]) < 0.01 and abs(p[2]-q[2]) < 0.01);
/* Design: draw a vector on a grid by dragging. Source: original. */
L: [[[1,1],[3,-4]],[[-3,-2],[-2,3]],[[2,-1],[-3,4]],[[2,-3],[3,2]],[[-3,-2],[1,3]],[[3,-2],[2,-1]],[[1,-2],[-4,-3]],[[-2,2],[4,1]],[[-2,1],[-4,2]],[[-3,1],[-1,4]]];
ix: 1+rand(10);
x0: L[ix][1][1]; y0: L[ix][1][2]; a: L[ix][2][1]; b: L[ix][2][2];
tgt: [x0+a, y0+b];
/* diagnostic points: drawn from O; BA drawn; across and up swapped; one sign changed */
dpos: [a, b]; drev: [x0-a, y0-b]; dswp: [x0+b, y0+a]; dsg1: [x0+a, y0-b]; dsg2: [x0-a, y0+b];
off: [x0+a+1, y0+b];
fl: [float(x0+a)+0.000001, y0+b];
